import pytest
from fastapi import FastAPI, Depends, Security
from fastapi.security import OAuth2PasswordBearer
from fastapi.dependencies.utils import SecurityScopes

oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

app = FastAPI()

def dep_c(security_scopes: SecurityScopes):
    return security_scopes.scopes

def dep_b(security_scopes: SecurityScopes = Security(oauth2_scheme, scopes=["scope_b"]), c=Depends(dep_c)):
    return {"b": security_scopes.scopes, "c": c}

def dep_a(security_scopes: SecurityScopes = Security(oauth2_scheme, scopes=["scope_a"]), b=Depends(dep_b)):
    return {"a": security_scopes.scopes, "b": b}

@app.get("/test")
def read_test(a=Depends(dep_a)):
    return a

def test_hierarchical_scopes():
    from fastapi.testclient import TestClient
    client = TestClient(app)

    # Mock the dependency resolution to check what security_scopes.scopes contains
    # Since we are testing the internal propagation, we can manually call the solve_dependencies
    # or just use a mock/override.

    # A better way to test this is to use FastAPI's dependency injection system.
    # We override the OAuth2PasswordBearer to avoid needing a real token.
    app.dependency_overrides[oauth2_scheme] = lambda: "fake-token"

    response = client.get("/test")
    assert response.status_code == 200
    data = response.json()

    # dep_a should have ["scope_a"]
    # dep_b should have ["scope_a", "scope_b"]
    # dep_c should have ["scope_a", "scope_b"]

    # Note: the return values we defined are:
    # dep_c returns scopes
    # dep_b returns {"b": scopes, "c": dep_c()}
    # dep_a returns {"a": scopes, "b": dep_b()}

    assert data["a"] == ["scope_a"]
    assert data["b"]["b"] == ["scope_a", "scope_b"]
    assert data["b"]["c"] == ["scope_a", "scope_b"]

def test_sibling_isolation():
    # Test that sibling dependencies don't leak scopes to each other
    app_sib = FastAPI()
    oauth2_sib = OAuth2PasswordBearer(tokenUrl="token")

    def dep_shared(security_scopes: SecurityScopes):
        return security_scopes.scopes

    def dep_1(security_scopes: SecurityScopes = Security(oauth2_sib, scopes=["scope_1"]), shared=Depends(dep_shared)):
        return {"shared": shared}

    def dep_2(security_scopes: SecurityScopes = Security(oauth2_sib, scopes=["scope_2"]), shared=Depends(dep_shared)):
        return {"shared": shared}

    @app_sib.get("/sib")
    def read_sib(d1=Depends(dep_1), d2=Depends(dep_2)):
        return {"d1": d1, "d2": d2}

    app_sib.dependency_overrides[oauth2_sib] = lambda: "fake-token"
    client_sib = TestClient(app_sib)
    response = client_sib.get("/sib")
    data = response.json()

    # dep_shared is used by both dep_1 and dep_2.
    # When called via dep_1, it should have ["scope_1"]
    # When called via dep_2, it should have ["scope_2"]
    assert data["d1"]["shared"] == ["scope_1"]
    assert data["d2"]["shared"] == ["scope_2"]

